<script lang="ts">import { router } from '../lib/router.svelte';import { processes } from '../lib/state/processes.svelte';import { prefs } from '../lib/state/prefs.svelte';const items = [{ path: '/', label: 'Overview', key: 'g o' }, { path: '/processes', label: 'Processes', key: 'g p' }, { path: '/logs', label: 'Logs', key: 'g l' }, { path: '/apps', label: 'Apps', key: 'g a' }, { path: '/config', label: 'Config', key: 'g c' }, { path: '/events', label: 'Events', key: 'g e' }, { path: '/projects', label: 'Projects', key: 'g j' }, { path: '/sessions', label: 'Sessions', key: 'g s' }, { path: '/integrations', label: 'Integrations', key: 'g i' }, { path: '/audit', label: 'Audit', key: 'g u' }, { path: '/settings', label: 'Settings', key: 'g t' }];function isActive(p: string) { return p === '/' ? router.path === '/' : router.path === p || router.path.startsWith(p + '/'); }</script><nav class="sidebar" class:collapsed={prefs.data.sidebarCollapsed} aria-label="Primary"><button class="collapse" onclick={() => prefs.set('sidebarCollapsed', !prefs.data.sidebarCollapsed)} aria-label="Toggle sidebar">{prefs.data.sidebarCollapsed ? '»' : '«'}</button>{#each items as it}<button class:active={isActive(it.path)} onclick={() => void router.navigate(it.path)} title={it.key}>{#if !prefs.data.sidebarCollapsed}{it.label}{#if it.path === '/processes' && processes.counts.failed > 0}<span class="badge">{processes.counts.failed}</span>{/if}{:else}{it.label[0]}{/if}</button>{/each}</nav><style>.sidebar{width:var(--sidebar-w);flex:none;display:flex;flex-direction:column;gap:2px;padding:var(--space-3);background:var(--bg-1);border-right:1px solid var(--border);overflow:auto}.sidebar.collapsed{width:52px}.sidebar button{text-align:left;background:transparent;border:none;border-radius:var(--radius);padding:var(--space-2) var(--space-3);color:var(--text-1)}.sidebar button.active{background:var(--accent-subtle);color:var(--text-0)}.badge{background:var(--err);color:white;border-radius:10px;padding:0 6px;font-size:var(--fs-xs);margin-left:6px}.collapse{align-self:flex-end}@media (max-width: 900px){.sidebar{width:52px}.sidebar button{font-size:0}.sidebar button::first-letter{font-size:var(--fs-md)}}@media (max-width: 640px){.sidebar{position:fixed;z-index:40;height:100%}}</style>
